      "title": "Change Text Case",
      "category": "backend",
      "templateCode": "def change_text_case(ctx, *, text, case: str='upper') -> dict:\n    s = as_text(text, 'text')\n    if case == 'upper':\n        return {'text': s.upper()}\n    if case == 'lower':\n        return {'text': s.lower()}\n    if case == 'title':\n        return {'text': s.title()}\n    raise CardError('invalid_input', f'Case must be upper, lower or title (got {case!r}).')",
