      "title": "Show Message Banner",
      "category": "ui",
      "templateCode": "def show_message_banner(ctx, *, message, variant: str='info', dismissible: bool=True, icon: str='') -> dict:\n    if not isinstance(message, str):\n        message = str(message)\n    if not message.strip():\n        raise CardError('required', 'Banner needs a message.')\n    if variant not in ('success', 'info', 'warning', 'error'):\n        variant = 'info'\n    node = view('display.banner', message=message, variant=variant, dismissible=dismissible, icon=icon)\n    return {'view': node}",
